#include <vector>
#include <cstddef>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    int globalMax = 0;

    #pragma omp parallel for reduction(max:globalMax)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        int degree = 0;
        const std::ptrdiff_t rowStart = i * static_cast<std::ptrdiff_t>(N);

        for (std::ptrdiff_t j = 0; j < static_cast<std::ptrdiff_t>(N); ++j) {
            degree += A[rowStart + j];
        }

        if (degree > globalMax) {
            globalMax = degree;
        }
    }

    return globalMax;
}
